            /** @enum {string} */
            severity: "CRITICAL" | "HIGH" | "MEDIUM" | "LOW" | "UNKNOWN";
            /** @description Vulnerable package name (e.g. openssl). */
            package: string;
            /** @description Installed package version (e.g. 1.1.1k-7). */
