        /** @description Project that owns this environment flag configuration. */
        FlagsProjectSlug: string;
        /** @description Named environment whose flag configuration is selected. */
        FlagsEnvironment: string;
        /** @description Application flag key to evaluate or filter retained evidence. */
        FlagsKey: string;
        /** @description Stable public UUID used by status permalinks. */
        PublicStatusEventID: string;
        /**
         * @description Dashboard session cookie. Sealed; opaque to the client
         *     (`HttpOnly; Secure; SameSite=Lax`). 7-day fixed lifetime.
         *     The browser sets it automatically on `/login` / `/signup`;
         *     the SDK uses the device-code flow instead and never sets
         *     this cookie.
         */
        CookieSession: string;
        /**
         * @description Idempotency key for the POST. Stored for 24h. On replay the server
         *     returns the original response with `Idempotent-Replayed: true`.
         */
        IdempotencyKey: string;
        /** @description Exact deployment pin. Mutually exclusive with X-Gregale-Release; checked again at delivery. */
        GregaleRevision: string;
        /** @description Immutable project release set. Defaults to the active set for project apps and is checked again at delivery. */
        GregaleRelease: string;
        /** @description App slug. Lowercase letters, digits, hyphens; must start and end with alnum. */
        Slug: string;
        /** @description 32-hex-char opaque ID (NOT canonical UUID). */
        Id32: string;
        /** @description Canonical UUID for a disposable execution. */
        ExecutionID: string;
        /** @description Canonical UUID for an execution artifact grant. */
        ExecutionArtifactGrantID: string;
        /** @description Canonical UUID for a deployment-attached app task. */
        AppTaskID: string;
        /** @description Opaque Gregale managed PostgreSQL resource identifier. */
        ManagedPostgresID: string;
        /** @description Gregale managed PostgreSQL cutover UUID. */
